#!/usr/bin/env python3
"""Versioned first-run tours and permanent Help controls for Phase 7."""
from __future__ import annotations

import json
from typing import Any, Dict

GUIDANCE_SCHEMA_VERSION = 1
GUIDANCE_RELEASE_VERSION = "2.5.3"
GUIDANCE_MANIFEST_VERSION = "2026.08.phase7.1"


def guidance_manifest() -> Dict[str, Any]:
    return {
        "schema_version": GUIDANCE_SCHEMA_VERSION,
        "release_version": GUIDANCE_RELEASE_VERSION,
        "manifest_version": GUIDANCE_MANIFEST_VERSION,
        "tours": {
            "desktop_compare": 2,
            "artist_ladder": 1,
            "gallery": 1,
            "generation_profiles": 1,
            "storage_settings": 2,
            "dedicated_duel": 2,
            "android_app": 2,
        },
        "shortcuts": {
            "desktop": [
                ["1", "Pick Image A"], ["2", "Pick Image B"], ["B", "Both bad"],
                ["T", "Tie"], ["I", "Invalid"], ["S", "Skip"], ["0", "Undo"],
                ["P", "Pause or resume generation"], ["L", "Show or hide rankings"],
            ],
            "phone": [
                ["Horizontal swipe / tap", "Choose A or B"],
                ["Two fingers down", "Tie"], ["Three fingers down", "Both bad"],
                ["Three fingers up", "Undo"],
                ["Long-press an image", "Image and artist options"],
                ["Swipe the bottom ribbon", "Gallery, Generation, Duel, or Artist Ladder"],
            ],
        },
    }


