DEDICATED_DUEL_GUIDANCE_BODY = r"""
<div id="duelGuidanceHelp"><div class="duel-guide-backdrop"></div><section class="duel-guide-dialog" role="dialog" aria-modal="true"><header class="duel-guide-head"><div><h2>Duel Help & Setup</h2><p>Gestures, long-press actions, pages, pairing, and troubleshooting.</p></div><button class="duel-guide-close" type="button">✕</button></header><div class="duel-guide-body"><section class="duel-guide-card"><h3>Help-button visibility</h3><label class="duel-guide-toggle"><span>Show floating Help button on this device</span><input id="duelHelpVisibleToggle" type="checkbox"></label></section><section class="duel-guide-card"><h3>Guided tour</h3><button id="duelRestartTour" type="button">Restart Duel / Android tour</button></section><section class="duel-guide-card"><h3>Voting gestures</h3><div class="duel-guide-list"><div class="duel-guide-row"><strong>Horizontal swipe / tap</strong><span>Choose Image A or B; reversing direction before release changes the pending choice</span></div><div class="duel-guide-row"><strong>Two fingers down</strong><span>Tie</span></div><div class="duel-guide-row"><strong>Three fingers down</strong><span>Both bad</span></div><div class="duel-guide-row"><strong>Three fingers up</strong><span>Undo</span></div><div class="duel-guide-row"><strong>Long-press image</strong><span>Favorite image or artist, tags, notes, reports, and related actions</span></div><div class="duel-guide-row"><strong>Bottom ribbon</strong><span>Swipe to Gallery, Generation, Duel, or Artist Ladder</span></div></div></section><section class="duel-guide-card"><h3>Pairing and recovery</h3><p>The Android app handles discovery and pairing natively. A revoked device returns to pairing. Create a new code on the PC under Storage / Settings.</p></section></div></section></div>
<div id="duelGuidanceTour"><div id="duelGuideShade" class="duel-guide-shade"></div><div id="duelGuideArrow" class="duel-guide-arrow"></div><section id="duelGuideTourCard" class="duel-guide-card-tour"><div id="duelGuideKicker" class="duel-guide-kicker"></div><div id="duelGuideTitle" class="duel-guide-title"></div><div id="duelGuideCopy" class="duel-guide-copy"></div><div class="duel-guide-actions"><button id="duelGuideSkip" type="button">Skip</button><button id="duelGuideBack" type="button">Back</button><button id="duelGuideNext" class="primary" type="button">Next</button></div></section></div>
"""

DEDICATED_DUEL_GUIDANCE_SCRIPT = r"""
<script id="artist-ranker-duel-guidance">
(() => {
  if(window.__artistRankerDuelGuidanceV240)return;window.__artistRankerDuelGuidanceV240=true;
  const nativeApp=/ArtistRankerApp\//i.test(navigator.userAgent),TOUR_ID=nativeApp?'android_app':'dedicated_duel',TOUR_VERSION=2,KEY='artistRanker.duelGuidance.v1',HELP_KEY='artistRanker.duelGuidance.helpButtonVisible',$=id=>document.getElementById(id),sleep=ms=>new Promise(r=>setTimeout(r,ms));
  const read=()=>{try{return JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{return{}}},write=s=>{try{localStorage.setItem(KEY,JSON.stringify(s))}catch{}};const saved=read();saved.completed=saved.completed||{};
  const steps=[
    {target:'#toolsButton',title:'Duel tools',copy:'This button sits above the images and opens options for the complete duel. In the Android app, the separate native menu handles connection, app settings, and Help.'},
    {target:'#gestureZone',title:'Voting gestures',copy:'Swipe horizontally or tap to choose A or B. Two fingers down means Tie, three down means Both bad, and three up means Undo. Reverse direction before release to change the pending choice.'},
    {target:'#cardA',title:'Long-press for image and artist actions',copy:'Long-press either image to open favorites, artist tags, private notes, bad-image reports, and related actions. The redundant image three-dot buttons have been removed.'},
    {target:'#resultCard',title:'Results and the navigation ribbon',copy:'After voting, rating changes and result details appear below the images. Swipe the bottom ribbon to move between Gallery, Generation, Duel, and Artist Ladder.'},
  ];
  let index=0,target=null;function helpVisible(){try{const v=localStorage.getItem(HELP_KEY);return v===null?true:v!=='false'}catch{return true}}function setHelpVisible(v,{native=true}={}){v=Boolean(v);try{localStorage.setItem(HELP_KEY,String(v))}catch{}document.documentElement.classList.toggle('artist-ranker-duel-help-hidden',!v);const t=$('duelHelpVisibleToggle');if(t)t.checked=v;if(native&&window.ArtistRankerNative?.setHelpButtonVisible){try{ArtistRankerNative.setHelpButtonVisible(v)}catch{}}}
  function place(){if(!target)return;const r=target.getBoundingClientRect(),shade=$('duelGuideShade'),card=$('duelGuideTourCard'),arrow=$('duelGuideArrow'),pad=7;shade.style.left=`${Math.max(5,r.left-pad)}px`;shade.style.top=`${Math.max(5,r.top-pad)}px`;shade.style.width=`${Math.max(28,Math.min(innerWidth-10,r.width+pad*2))}px`;shade.style.height=`${Math.max(28,Math.min(innerHeight-10,r.height+pad*2))}px`;const cr=card.getBoundingClientRect(),below=r.bottom+18+cr.height<=innerHeight,top=below?r.bottom+18:Math.max(10,r.top-cr.height-18),left=Math.max(10,Math.min(innerWidth-cr.width-10,r.left+r.width/2-cr.width/2));card.style.left=`${left}px`;card.style.top=`${top}px`;arrow.style.left=`${Math.max(left+24,Math.min(left+cr.width-30,r.left+r.width/2-8))}px`;arrow.style.top=`${below?top-8:top+cr.height-8}px`;arrow.style.transform=below?'rotate(45deg)':'rotate(225deg)'}
  async function show(){const step=steps[index];target=document.querySelector(step.target)||document.body;if(step.target==='#resultCard'&&target.classList.contains('empty'))target=document.querySelector('#navigationRibbon')||target;try{target.scrollIntoView({behavior:'smooth',block:'center'})}catch{}await sleep(190);$('duelGuideKicker').textContent=`${nativeApp?'Android app':'Duel page'} · ${index+1} of ${steps.length}`;$('duelGuideTitle').textContent=step.title;$('duelGuideCopy').textContent=step.copy;$('duelGuideBack').disabled=index===0;$('duelGuideNext').textContent=index===steps.length-1?'Finish':'Next';$('duelGuidanceTour').classList.add('open');requestAnimationFrame(place)}
  function finish(){saved.completed[TOUR_ID]=TOUR_VERSION;write(saved);$('duelGuidanceTour').classList.remove('open')}function startTour(){if(nativeApp&&window.ArtistRankerNative?.restartNativeTour){try{ArtistRankerNative.restartNativeTour();$('duelGuidanceHelp').classList.remove('open');return}catch{}}index=0;$('duelGuidanceHelp').classList.remove('open');show()}
  function build(){if($('duelHelpBtn'))return;const b=document.createElement('button');b.id='duelHelpBtn';b.type='button';b.textContent='? Help';b.onclick=()=>$('duelGuidanceHelp').classList.add('open');document.body.appendChild(b);$('duelGuidanceHelp').querySelector('.duel-guide-backdrop').onclick=()=>$('duelGuidanceHelp').classList.remove('open');$('duelGuidanceHelp').querySelector('.duel-guide-close').onclick=()=>$('duelGuidanceHelp').classList.remove('open');$('duelRestartTour').onclick=startTour;$('duelGuideSkip').onclick=finish;$('duelGuideBack').onclick=()=>{if(index>0){index--;show()}};$('duelGuideNext').onclick=()=>{if(index>=steps.length-1)finish();else{index++;show()}};$('duelHelpVisibleToggle').onchange=e=>setHelpVisible(e.currentTarget.checked);window.addEventListener('scroll',()=>requestAnimationFrame(place),true);window.addEventListener('resize',()=>requestAnimationFrame(place));setHelpVisible(helpVisible(),{native:false});
    if(nativeApp&&window.ArtistRankerNative){const overlay=$('pairingOverlay');if(overlay){new MutationObserver(()=>{if(overlay.classList.contains('open')){try{ArtistRankerNative.pairingRequired(String($('pairingStatus')?.textContent||'Pairing required'))}catch{}overlay.classList.remove('open')}}).observe(overlay,{attributes:true,attributeFilter:['class']})}}
    if(!nativeApp&&Number(saved.completed[TOUR_ID]||0)<TOUR_VERSION)setTimeout(startTour,900)}
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',build,{once:true});else build();window.ArtistRankerDuelGuidance={startTour,openHelp:()=>$('duelGuidanceHelp')?.classList.add('open'),setHelpButtonVisible:setHelpVisible};
})();
</script>
"""


def enhance_dedicated_duel_html(source: str) -> str:
    text = str(source or "")
    if "artist-ranker-duel-guidance" in text:
        return text
    if "</head>" in text:
        text = text.replace("</head>", DEDICATED_DUEL_GUIDANCE_STYLE + "</head>", 1)
    if "</body>" in text:
        text = text.replace("</body>", DEDICATED_DUEL_GUIDANCE_BODY + DEDICATED_DUEL_GUIDANCE_SCRIPT + "</body>", 1)
    return text
